mapper.select:
SELECT 
FROM file_entry e

WHERE e.owner_id = #{query.ownerId}
  AND e.parent_id = #{query.parentId}

  AND e.deleted_at IS NULL


  AND (
    e.name LIKE CONCAT('%', #{query.query}, '%')
    OR EXISTS (
      SELECT 1
      FROM file_tag search_ft
      JOIN tag search_tag ON search_tag.id = search_ft.tag_id
      WHERE search_ft.entry_id = e.id
        AND search_tag.name LIKE CONCAT('%', #{query.query}, '%')
    )
  )


  AND EXISTS (
    SELECT 1
    FROM file_tag filter_ft
    JOIN tag filter_tag ON filter_tag.id = filter_ft.tag_id
    WHERE filter_ft.entry_id = e.id
      AND filter_tag.name = #{query.tag}
  )


  AND e.entry_kind = 'FOLDER'


  AND e.entry_kind = 'FILE'
  AND LOWER(SUBSTRING_INDEX(e.name, '.', -1)) IN (
    'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx',
    'pdf', 'txt', 'md', 'ofd'
  )


  AND e.entry_kind = 'FILE'
  AND LOWER(SUBSTRING_INDEX(e.name, '.', -1)) IN (
    'png', 'jpg', 'jpeg', 'webp', 'gif',
    'mp4', 'mov', 'mp3', 'wav', 'm4a'
  )


  AND e.entry_kind = 'FILE'
  AND LOWER(SUBSTRING_INDEX(e.name, '.', -1)) IN (
    'js', 'ts', 'vue', 'java', 'py', 'go', 'rs',
    'c', 'cpp', 'html', 'css', 'json', 'yaml', 'yml',
    'xml', 'sql'
  )


  AND (
    CASE WHEN e.entry_kind = 'FOLDER' THEN 0 ELSE 1 END
      > #{query.cursor.folderRank}
    OR (
      CASE WHEN e.entry_kind = 'FOLDER' THEN 0 ELSE 1 END
        = #{query.cursor.folderRank}
      AND


          (
            e.name > #{query.cursor.name}
            OR (e.name = #{query.cursor.name}
                AND e.id > #{query.cursor.id})
          )


          (
            COALESCE(o.size_bytes, 0) < #{query.cursor.size}
            OR (COALESCE(o.size_bytes, 0) = #{query.cursor.size}
                AND e.id < #{query.cursor.id})
          )


          (
            e.updated_at > #{query.cursor.modifiedAt}
            OR (e.updated_at = #{query.cursor.modifiedAt}
                AND e.id > #{query.cursor.id})
          )


          (
            e.updated_at < #{query.cursor.modifiedAt}
            OR (e.updated_at = #{query.cursor.modifiedAt}
                AND e.id < #{query.cursor.id})
          )


    )
  )

ORDER BY
  CASE WHEN e.entry_kind = 'FOLDER' THEN 0 ELSE 1 END,


    e.name ASC, e.id ASC


    COALESCE(o.size_bytes, 0) DESC, e.id DESC


    e.updated_at ASC, e.id ASC


    e.updated_at DESC, e.id DESC


LIMIT #{query.limit}

